package vn.ptit.slms.counting;
import vn.ptit.slms.common.*;import vn.ptit.slms.security.*;import vn.ptit.slms.stock.*;import vn.ptit.slms.approval.*;import org.springframework.stereotype.Service;import java.util.*;import java.math.*;import static vn.ptit.slms.common.Db.*;
@Service public class CountService {
 private final Db db;private final AccessGuard g;private final StockService stock;private final ApprovalService approval;private final Json json;
 public CountService(Db d,AccessGuard g,StockService s,ApprovalService a,Json j){db=d;this.g=g;stock=s;approval=a;json=j;}
 public Object list(long w){g.warehouse(w);return db.rows("select * from count_session where warehouse_id=? order by id desc limit 200",w);}
 public Map<String,Object> detail(long w,long id){g.warehouse(w);var s=new LinkedHashMap<>(db.one("select * from count_session where warehouse_id=? and id=?",w,id));String filter=g.role().equals("ACT03")?" and i.assigned_to=?":"";Object[] args=g.role().equals("ACT03")?new Object[]{id,g.actor()}:new Object[]{id};s.put("items",db.rows("select i.*,s.code sku_code,l.code location_code,a.id attempt_id,a.counted_qty,a.book_at_count,a.delta,a.cutoff_seq,a.reconcile_seq from count_item i join sku s on s.id=i.sku_id join location l on l.id=i.location_id left join count_attempt a on a.item_id=i.id and a.superseded_at is null where i.session_id=?"+filter+" order by i.id",args));return s;}
 @SuppressWarnings("unchecked") public Object create(long w,Map<String,Object> p){g.roles("ACT02");var keys=(List<Map<String,Object>>)p.get("items");Problem.require(keys!=null&&!keys.isEmpty(),"ITEMS","Cần chọn phạm vi kiểm kê.");long id=db.id("insert into count_session(warehouse_id,code,status,planned_at,owner_id) values (?,?,'DRAFT',clock_timestamp(),?) returning id",w,"KK-"+UUID.randomUUID().toString().substring(0,8).toUpperCase(),g.actor());for(var k:keys){stock.lock(w,List.of(new StockService.Key(lng(k.get("locationId")),lng(k.get("skuId")))));db.run("insert into count_item(warehouse_id,session_id,location_id,sku_id,status) values (?,?,?,?,'WAITING')",w,id,lng(k.get("locationId")),lng(k.get("skuId")));}return detail(w,id);}
 public Object sessionAction(long w,long id,String action,Map<String,Object> p){g.roles("ACT02");var s=db.one("select * from count_session where warehouse_id=? and id=? for update",w,id);Problem.require(lng(s.get("version"))==lng(p.get("version")),"STALE_VERSION","Đợt đã thay đổi.");var items=db.rows("select * from count_item where session_id=? order by sku_id,location_id for update",id);
 if(action.equals("open")){Problem.require(s.get("status").equals("DRAFT"),"STATE","Đợt không còn nháp.");stock.lock(w,items.stream().map(i->new StockService.Key(lng(i.get("location_id")),lng(i.get("sku_id")))).toList());for(var i:items){var b=stock.balance(w,new StockService.Key(lng(i.get("location_id")),lng(i.get("sku_id"))));db.run("update count_item set book_at_t0=?,t0_seq=? where id=?",b.get("book_qty"),b.get("last_seq"),i.get("id"));}db.run("update count_session set status='OPEN',opened_at=clock_timestamp(),version=version+1 where id=?",id);}
 else if(action.equals("close")){Problem.require(s.get("status").equals("OPEN")&&items.stream().allMatch(i->Set.of("MATCHED","ADJUSTED").contains(i.get("status"))),"OPEN_ITEMS","Chỉ đóng đợt khi mọi dòng đã khớp hoặc đã điều chỉnh.");db.run("insert into count_minutes(session_id,locked_at,locked_by,note,snapshot) values (?,clock_timestamp(),?,?,?::jsonb)",id,g.actor(),text(p,"note"),json.write(detail(w,id)));db.run("update count_item set status='CLOSED',version=version+1 where session_id=?",id);db.run("update count_session set status='CLOSED',closed_at=clock_timestamp(),version=version+1 where id=?",id);}else throw new IllegalArgumentException();return detail(w,id);}
 public Object itemAction(long w,long id,String action,Map<String,Object> p){var source=db.one("select session_id from count_item where warehouse_id=? and id=?",w,id);db.one("select * from count_session where id=? and status='OPEN' for update",source.get("session_id"));var i=db.one("select * from count_item where warehouse_id=? and id=? for update",w,id);Problem.require(lng(i.get("version"))==lng(p.get("version")),"STALE_VERSION","Dòng kiểm kê đã thay đổi.");String state=i.get("status").toString();var k=new StockService.Key(lng(i.get("location_id")),lng(i.get("sku_id")));String next=state;
 switch(action){case "assign":g.roles("ACT02");Problem.require(Set.of("WAITING","ASSIGNED").contains(state),"STATE","Chỉ phân công trước khi đếm.");String user=required(p,"username");Problem.require(db.id("select count(*) from app_user u join user_warehouse a on a.username=u.username where u.username=? and a.warehouse_id=? and u.role='ACT03' and u.active",user,w)>0,"ASSIGNEE","Người đếm phải là nhân viên thuộc kho.");db.run("update count_item set assigned_to=? where id=?",user,id);next="ASSIGNED";break;
 case "start":g.roles("ACT03");Problem.require(g.actor().equals(i.get("assigned_to"))&&Set.of("ASSIGNED","RECOUNT").contains(state),"ASSIGNEE","Không đúng người/bước kiểm đếm.");stock.lock(w,List.of(k));stock.unlocked(w,k);Problem.require(db.id("select count(*) from reservation where warehouse_id=? and location_id=? and sku_id=? and status='ACTIVE' and qty_picked>0",w,k.location(),k.sku())==0,"PICKED_STOCK","Hoàn trả hoặc hoàn tất hàng đã soạn trước kiểm đếm.");db.run("insert into count_attempt(warehouse_id,item_id,location_id,sku_id,attempt_no,counted_by) select ?,?,?,?,coalesce(max(attempt_no),0)+1,? from count_attempt where item_id=?",w,id,k.location(),k.sku(),g.actor(),id);next="COUNTING";break;
 case "record":{g.roles("ACT03");Problem.require(g.actor().equals(i.get("assigned_to"))&&state.equals("COUNTING"),"STATE","Không có lượt đếm của bạn đang mở.");stock.lock(w,List.of(k));var b=stock.balance(w,k);db.run("update count_attempt set counted_at=clock_timestamp(),counted_qty=?,book_at_count=?,cutoff_seq=?,condition_note=? where item_id=? and superseded_at is null and counted_at is null",qty(p.get("qty")),b.get("book_qty"),b.get("last_seq"),text(p,"conditionNote"),id);next="COUNTED";break;}
 case "reconcile":{g.roles("ACT02","ACT03");Problem.require(state.equals("COUNTED"),"STATE","Cần kết quả đếm trước đối chiếu.");if(g.role().equals("ACT03"))Problem.require(g.actor().equals(i.get("assigned_to")),"ASSIGNEE","Không được giao dòng này.");stock.lock(w,List.of(k));var b=stock.balance(w,k);var a=db.one("select * from count_attempt where item_id=? and superseded_at is null",id);db.run("update count_attempt set reconcile_seq=?,reconciled_at=clock_timestamp(),reconciled_by=? where id=?",b.get("last_seq"),g.actor(),a.get("id"));next=dec(a.get("delta")).signum()==0?"MATCHED":"VARIANCE";break;}
 case "request-adjustment":{g.roles("ACT03");Problem.require(state.equals("VARIANCE")&&g.actor().equals(i.get("assigned_to")),"STATE","Chỉ người đếm được lập đề nghị từ dòng lệch.");var a=db.one("select * from count_attempt where item_id=? and superseded_at is null and reconciled_at is not null",id);long adj=db.id("insert into adjustment(warehouse_id,kind,count_attempt_id,status,created_by,reason) values (?,'COUNT',?,'PENDING',?,?) returning id",w,a.get("id"),g.actor(),required(p,"reason"));db.run("insert into adjustment_line(adjustment_id,line_no,warehouse_id,location_id,sku_id,delta_book) values (?,1,?,?,?,?)",adj,w,k.location(),k.sku(),a.get("delta"));db.run("update adjustment set evidence=?::jsonb where id=?",json.write(p.getOrDefault("evidenceIds",List.of())),adj);approval.submit(w,"adjustment",adj,0,g.actor(),dec(a.get("delta")),a,false);next="PENDING";break;}
 case "recount":{g.roles("ACT02");Problem.require(!Set.of("ADJUSTED","CLOSED","WAITING","ASSIGNED").contains(state),"STATE","Không được thay kết quả đã áp dụng; mở đợt mới.");required(p,"reason");stock.lock(w,List.of(k));for(var a:db.rows("select ad.id from adjustment ad join count_attempt a on a.id=ad.count_attempt_id where a.item_id=? and ad.status='PENDING' for update of ad",id)){approval.cancel("adjustment",lng(a.get("id")));db.run("update adjustment set status='SUPERSEDED',version=version+1 where id=?",a.get("id"));}db.run("update count_attempt set superseded_at=clock_timestamp(),supersede_reason=? where item_id=? and superseded_at is null",text(p,"reason"),id);next="RECOUNT";break;}
 default:throw new IllegalArgumentException();}
 db.run("update count_item set status=?,version=version+1 where id=?",next,id);return detail(w,lng(i.get("session_id")));}
}
